def score(plan):
    ds = plan['districts']
    n = len(ds)
    if n == 0:
        return 0.0
    k = min(plan['budget'], n)
    if k <= 0:
        return 0.0
    got = 0
    for d in ds:
        if d['new_facilities'] >= 1:
            got += 1
    return float(min(1.0, got / k))

def score(plan):
    ds = plan['districts']
    low = []
    for d in ds:
        if d['coverage_before_pct'] < 30:
            low.append(d)
    if len(low) == 0:
        return 1.0
    total = 0
    for d in ds:
        total += d['new_facilities']
    if total <= 0:
        return 0.0
    served = 0
    for d in low:
        if d['new_facilities'] >= 1:
            served += 1
    k = min(total, len(low))
    return float(min(1.0, served / k))

def score(plan):
    ds = plan['districts']
    total = 0
    for d in ds:
        total += d['new_facilities']
    if total <= 0:
        return 0.0
    cap = max(1.0, total / 3.0)
    ok = 0.0
    for d in ds:
        ok += min(d['new_facilities'], cap)
    return float(max(0.0, min(1.0, ok / total)))

def score(plan):
