def score(plan):
    ds = plan['districts']
    total = 0
    for d in ds:
        total += d['new_facilities']
    if total <= 0:
        return 0.0
    n = len(ds)
    pairs = 0
    pts = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            a = ds[i]
            b = ds[j]
            if a['population'] == b['population']:
                continue
            if a['population'] > b['population']:
                big = a
                small = b
            else:
                big = b
                small = a
            pairs += 1
            if big['new_facilities'] > small['new_facilities']:
                pts += 1.0
            elif big['new_facilities'] == small['new_facilities']:
                pts += 0.5
    if pairs == 0:
        return 1.0
    return float(pts / pairs)
